func TestReproLeak(t *testing.T) {
	baseline := liveGoroutines()
	l := &Logger{store: &blockingStore{}}
	for i := 0; i < 5; i++ { l.LogAsync(AuditEvent{}) }
	time.Sleep(50 * time.Millisecond)
	if liveGoroutines() <= baseline { t.Fatal("goroutines leaked") }
}
